"use client";

import React, { useMemo, useState } from "react";
import { useParams, useRouter } from "next/navigation";

import { useAuth } from "@/ui/auth/useAuth";
import { useItemDetailSWR } from "@/services/useItemDetailSWR";

import type { Item } from "@/types/item";
import { getImageUrl } from "@/utils/utils";

import styles from "./W-Purchase-Confirm.module.css";

export default function PurchaseConfirmPage() {
  const router = useRouter();
  const params = useParams();
  const {
    isAuthenticated,
    isLoading: isAuthLoading,
    user,
    apiClient,
  } = useAuth();

  /* =========================
     🧩 itemId 解決
  ========================= */
 const itemId = useMemo(() => {
   const raw = params.items_id;
   const id = Array.isArray(raw) ? raw[0] : raw;
   const n = Number(id);
   return Number.isNaN(n) ? null : n;
 }, [params.items_id]);

  /* =========================
     📦 Item Detail
  ========================= */
  const { item, isLoading: isItemLoading, isError } = useItemDetailSWR(itemId);

  /* =========================
     💳 支払い方法
  ========================= */
  const [payment, setPayment] = useState<"convenience" | "card" | "">("");

  const canPurchase =
    isAuthenticated &&
    !!item &&
    item.remain > 0 &&
    payment !== "" &&
    !!user?.address;

  /* =========================
     🧠 ローディング判定
  ========================= */
  const isPageLoading = isAuthLoading || isItemLoading;

  /* =========================
     🧾 Purchase Action
  ========================= */
  const submitPurchase = async () => {
    if (!canPurchase || !item || !apiClient) return;

    try {
      if (payment === "card") {
        const res = await apiClient.post("/purchase/card", {
          item_id: item.id,
        });

        if (res.data?.stripe_url) {
          window.location.href = res.data.stripe_url;
          return;
        }
        throw new Error("Stripe URL が取得できませんでした");
      }

      if (payment === "convenience") {
        await apiClient.post("/purchase/convenience", {
          item_id: item.id,
        });

        router.push("/thanks/buy");
      }
    } catch (e) {
      console.error("purchase error:", e);
      alert("購入処理に失敗しました");
    }
  };

  /* =========================
     🛑 Guard
  ========================= */
  if (isPageLoading) {
    return (
      <div className={styles.loadingBox}>
        <div className={styles.spinner}></div>
        <p>読み込み中...</p>
      </div>
    );
  }

  if (isError || !item) {
    return <p className={styles.errorText}>商品が見つかりませんでした。</p>;
  }

  if (!isAuthenticated) {
    router.push("/login");
    return null;
  }

  /* =========================
     🎨 UI
  ========================= */
  return (
    <div className={styles.wrapper}>
      <h1 className={styles.pageTitle}>購入内容の確認</h1>

      {/* 商品情報 */}
      <div className={styles.itemCard}>
        <img
          src={getImageUrl(item.item_image)}
          alt={item.name}
          className={styles.itemImage}
        />

        <div className={styles.itemInfo}>
          <p className={styles.itemName}>{item.name}</p>
          <p className={styles.itemPrice}>¥{item.price.toLocaleString()}</p>
        </div>
      </div>

      {/* 支払い方法 */}
      <div className={styles.section}>
        <h2 className={styles.sectionTitle}>支払い方法</h2>

        <label className={styles.radio}>
          <input
            type="radio"
            value="convenience"
            checked={payment === "convenience"}
            onChange={() => setPayment("convenience")}
          />
          コンビニ払い
        </label>

        <label className={styles.radio}>
          <input
            type="radio"
            value="card"
            checked={payment === "card"}
            onChange={() => setPayment("card")}
          />
          クレジットカード（Stripe）
        </label>
      </div>

      {/* 配送先 */}
      <div className={styles.section}>
        <div className={styles.addressHeader}>
          <h2 className={styles.sectionTitle}>配送先</h2>
          <button
            className={styles.linkBtn}
            onClick={() =>
              router.push(`/purchase/address/${item.id}/${user!.id}`)
            }
          >
            変更する
          </button>
        </div>

        {user?.address ? (
          <div className={styles.addressBox}>
            <p>〒{user.post_number}</p>
            <p>{user.address}</p>
            {user.building && <p>{user.building}</p>}
          </div>
        ) : (
          <p className={styles.warnText}>配送先住所が未登録です</p>
        )}
      </div>

      {/* 購入ボタン */}
      <div className={styles.purchaseBox}>
        <button
          onClick={submitPurchase}
          disabled={!canPurchase}
          className={styles.purchaseBtn}
        >
          購入する
        </button>
      </div>
    </div>
  );
}
